CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_save_profile_results`(
  i_playerid    INT(11) UNSIGNED
, i_version_no  VARCHAR(15)
, i_frames    INT(11) UNSIGNED
, i_min_time    FLOAT
, i_max_time    FLOAT
, i_total_time  FLOAT
, i_over_100    INT(11) UNSIGNED
, i_over_300    INT(11) UNSIGNED
, i_over_500    INT(11) UNSIGNED
