CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_score_analysis`(
)
    MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
  DECLARE l_last_persona_id, l_last_rank, l_personaid, l_branchid, l_old_rank, l_new_rank INT(11) UNSIGNED ;
  DECLARE l_last_recorded, l_recorded DATETIME ;

  DECLARE l_done TINYINT(1) UNSIGNED DEFAULT 0 ;

  DECLARE curs CURSOR FOR
    SELECT  r.personaid, r.recorded, p.branchid, r.old_rank, r.new_rank
      FROM  `audit`.`rank` r
        INNER JOIN `wwiionline`.`wwii_persona` p USING (personaid)
     ORDER  BY 1, 2
  ;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_done = 1 ;

  OPEN curs ;
  REPEAT
    FETCH curs INTO l_personaid, l_recorded, l_branchid, l_old_rank, l_new_rank ;
    IF NOT l_done THEN
      IF l_personaid = l_last_persona_id AND l_old_rank = l_last_rank AND l_new_rank = l_last_rank + 1 THEN
        REPLACE INTO `audit`.`score_analysis`
          (personaid, branchid, rankid, first_entry, last_entry, hours, complete)
        VALUES
          ( l_personaid, l_branchid, l_new_rank, l_last_recorded, l_recorded
          , FLOOR((UNIX_TIMESTAMP(l_recorded) - UNIX_TIMESTAMP(l_last_recorded)) / 3600 + 0.5)
          , 1
          )
        ;
      END IF ;
      SET l_last_persona_id = l_personaid, l_last_rank = l_new_rank, l_last_recorded = l_recorded ;
    END IF ;
  UNTIL l_done END REPEAT ;
  CLOSE curs ;

END ;;
DELIMITER ;
