DROP TABLE IF EXISTS `chat_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `chat_events` (
  `event_oid` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `event_stamp` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `category` varchar(4) NOT NULL DEFAULT '',
  `event` varchar(10) NOT NULL DEFAULT '',
  `callsign` char(10) NOT NULL,
  `parameter` text NOT NULL,
  `data` text NOT NULL,
  PRIMARY KEY (`event_oid`),
  KEY `event_stamp` (`event_stamp`),
  KEY `ce_callsign` (`callsign`(2)),
  KEY `ce_category` (`category`),
  KEY `cat_st` (`category`,`event_stamp`)
) ENGINE=MyISAM DEFAULT CHARSET=ucs2;
/*!40101 SET character_set_client = @saved_cs_client */;

DROP TABLE IF EXISTS `chat_friends`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `chat_friends` (
  `playerid` int(11) unsigned NOT NULL DEFAULT '0',
  `target` char(10) NOT NULL,
  PRIMARY KEY (`playerid`,`target`),
  CONSTRAINT `fk_cf_playerid` FOREIGN KEY (`playerid`) REFERENCES `wwii_player` (`playerid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=ucs2;
/*!40101 SET character_set_client = @saved_cs_client */;

DROP TABLE IF EXISTS `chat_group_audit`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `chat_group_audit` (
  `server` varchar(8) NOT NULL DEFAULT '',
  `playerid` int(11) NOT NULL DEFAULT '0',
  `eventtime` datetime DEFAULT NULL,
  `cmd` char(3) NOT NULL DEFAULT '',
  `user` varchar(10) NOT NULL DEFAULT '',
  `group_oid` int(11) NOT NULL DEFAULT '0',
  `cga_oid` int(11) NOT NULL AUTO_INCREMENT,
  PRIMARY KEY (`cga_oid`),
  KEY `server` (`server`,`playerid`,`eventtime`),
  KEY `cmd` (`cmd`),
  KEY `group_oid` (`group_oid`)
) ENGINE=MyISAM DEFAULT CHARSET=ucs2;
/*!40101 SET character_set_client = @saved_cs_client */;

DROP TABLE IF EXISTS `chat_group_cmds`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `chat_group_cmds` (
  `group_oid` smallint(6) unsigned NOT NULL COMMENT 'auth.chat_groups group id',
  `cmd_oid` int(11) unsigned NOT NULL COMMENT 'wwiionline.chat_commands command id being granted',
  `modified` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  KEY `fk_cgc_groupid_idx` (`group_oid`),
  KEY `fk_cgc_cmdid_idx` (`cmd_oid`),
  CONSTRAINT `fk_cgc_cmdid` FOREIGN KEY (`cmd_oid`) REFERENCES `chat_commands` (`cmd_oid`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_cgc_groupid` FOREIGN KEY (`group_oid`) REFERENCES `auth`.`chat_groups` (`group_oid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=ucs2 COMMENT='List of commands granted by specific chat groups';
/*!40101 SET character_set_client = @saved_cs_client */;

