/*!50003 CREATE*/ /*!50017 DEFINER=`wwiiol`@`localhost`*/ /*!50003 TRIGGER `wwiionline`.`tai_persona_scoring`
  AFTER INSERT ON `wwiionline`.`wwii_persona` FOR EACH ROW
BEGIN
   INSERT INTO `audit`.`score`
          (personaid, old_rank, new_rank, old_score, new_score)
   VALUES (NEW.personaid, 0, NEW.rankid, 0, NEW.rankpoints);
   INSERT INTO `audit`.`rank`
      (personaid, old_rank, new_rank)
   VALUES (NEW.personaid, 0, 0);
END */;;
