/*!50003 CREATE*/ /*!50017 DEFINER=`wwiiol`@`localhost`*/ /*!50003 TRIGGER `wwiionline`.`tau_persona_scoring`
  AFTER UPDATE ON `wwiionline`.`wwii_persona` FOR EACH ROW
BEGIN
   IF NEW.rankid <> OLD.rankid OR NEW.rankpoints <> OLD.rankpoints THEN
     INSERT INTO `audit`.`score`
            (personaid, old_rank, new_rank, old_score, new_score)
     VALUES (NEW.personaid, OLD.rankid, NEW.rankid, OLD.rankpoints, NEW.rankpoints);
   END IF;
   IF NEW.rankid <> OLD.rankid THEN
     INSERT INTO `audit`.`rank`
            (personaid, old_rank, new_rank) 
     VALUES (NEW.personaid, OLD.rankid, NEW.rankid);
   END IF;
END */;;
DELIMITER ;
