CREATE TABLE `wwii_persona_hcrankaudit` (
  `auditit` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `playerid` int(10) unsigned NOT NULL DEFAULT '0',
  `countryid` int(10) unsigned NOT NULL DEFAULT '0',
  `branchid` int(10) unsigned NOT NULL DEFAULT '0',
  `oldrankid` int(10) unsigned NOT NULL DEFAULT '0',
  `newrankid` int(10) unsigned NOT NULL DEFAULT '0',
  `added` datetime DEFAULT NULL,
  PRIMARY KEY (`auditit`),
  KEY `playerid` (`playerid`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1;
