CREATE TABLE `wwii_player` (
  `playerid` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `customerid` int(11) unsigned NOT NULL,
  `callsign` char(10) NOT NULL,
  `modified` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `added` datetime DEFAULT NULL,
  `lockside` int(11) DEFAULT '0',
  `squadid` int(11) unsigned DEFAULT '0',
  `locktime` int(11) DEFAULT NULL,
  `isplaynet` tinyint(4) unsigned DEFAULT NULL,
  `player_decal` int(11) NOT NULL DEFAULT '0',
  `officer_unit_id` int(11) unsigned NOT NULL DEFAULT '0',
  `squad_rank` int(4) unsigned DEFAULT '0',
  `last_login` datetime DEFAULT NULL,
  `last_poll` int(11) unsigned NOT NULL DEFAULT '0',
  `squad_joined` datetime DEFAULT NULL,
  `last_online` datetime DEFAULT NULL,
  `total_time_played` int(11) unsigned DEFAULT NULL,
  `squad_time_played` int(11) unsigned DEFAULT NULL,
  PRIMARY KEY (`playerid`),
  UNIQUE KEY `customerid` (`customerid`),
  UNIQUE KEY `callsign` (`callsign`),
  KEY `plyrsquad` (`squadid`,`squad_rank`,`squad_joined`),
  KEY `lockidx` (`lockside`,`locktime`),
  KEY `w2p_mod` (`modified`),
  KEY `plyrcall` (`playerid`,`callsign`),
  CONSTRAINT `fk_customerid` FOREIGN KEY (`customerid`) REFERENCES `auth`.`auth_customer` (`customerid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1256737 DEFAULT CHARSET=ucs2;
