  `xoID` int(11) unsigned NOT NULL DEFAULT '0',
  KEY `fk_sa_squadid_idx` (`squadID`),
  CONSTRAINT `fk_sa_squadid` FOREIGN KEY (`squadID`) REFERENCES `wwii_squads` (`squadid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=ucs2 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

DROP TABLE IF EXISTS `wwii_squads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `wwii_squads` (
  `squadid` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(40) NOT NULL DEFAULT '',
  `short_name` char(10) NOT NULL,
  `description` text NOT NULL,
  `password` text NOT NULL,
  `homepage` text,
  `active` tinyint(1) unsigned NOT NULL DEFAULT '0',
  `recruiting` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `flags` bigint(20) DEFAULT '0',
  `created` datetime DEFAULT NULL,
  `modified` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `creatorid` int(11) unsigned NOT NULL DEFAULT '0',
  `pri_language` smallint(2) unsigned NOT NULL DEFAULT '0',
  `sec_language` smallint(2) unsigned NOT NULL DEFAULT '0',
  `def_country` smallint(2) unsigned NOT NULL DEFAULT '0',
  `def_branch` smallint(2) unsigned NOT NULL DEFAULT '0',
  `def_brigade` int(11) unsigned NOT NULL DEFAULT '0',
  `motd` text,
  `rookie_days` smallint(6) unsigned DEFAULT '7',
  `last_joined` datetime DEFAULT NULL,
  `last_joiner` varchar(8) DEFAULT NULL,
  `disbanded` tinyint(1) unsigned NOT NULL DEFAULT '0',
  `voting` tinyint(1) unsigned DEFAULT '1',
  `name_changed` int(11) unsigned DEFAULT NULL,
  `size_warning` datetime DEFAULT NULL,
  `squad_closed` datetime DEFAULT NULL,
  `voice_info` varchar(80) DEFAULT NULL,
  `squad_night` varchar(8) CHARACTER SET latin1 NOT NULL DEFAULT '0,0,0',
  `slogan` varchar(80) DEFAULT NULL,
  PRIMARY KEY (`squadid`),
  UNIQUE KEY `short_name` (`short_name`),
  KEY `idx_modified` (`modified`),
  KEY `fk_creatorid` (`creatorid`),
  CONSTRAINT `fk_creatorid` FOREIGN KEY (`creatorid`) REFERENCES `wwii_player` (`playerid`) ON DELETE NO ACTION ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10810 DEFAULT CHARSET=ucs2 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

