CREATE DEFINER=`wwiiol`@`localhost` FUNCTION `f_player_permissions`( i_player_id INT(11) UNSIGNED ) RETURNS bigint(20) unsigned
    READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
  DECLARE l_permissions BIGINT(20) UNSIGNED DEFAULT 0;
  SELECT  BIT_OR(pe.maskvalue) INTO l_permissions
    FROM  wwiionline.wwii_player_permiss wpp
      INNER JOIN auth.wwii_permissions pe
        USING (`permissionid`)
   WHERE  wpp.playerid = i_player_id
  ;
  RETURN l_permissions;
END ;;
DELIMITER ;
