CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_chat_group_summary`(
)
    READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
  SELECT  cg.group_oid
       ,  IF(cg.enabled='Y', 1, 0) AS enabled
       ,  MAX(IF(cgr.branchid = 1, cgr.max_rank, NULL)) AS max_army_rank
       ,  MAX(IF(cgr.branchid = 2, cgr.max_rank, NULL)) AS max_air_rank
       ,  MAX(IF(cgr.branchid = 3, cgr.max_rank, NULL)) AS max_navy_rank
       ,  cg.max_squad_rank
       ,  cg.grants
       ,  GROUP_CONCAT(cgv.vehtype_oid) AS vehtype_oids
    FROM  `auth`.`chat_groups` cg
      LEFT OUTER JOIN `wwiionline`.`chat_group_ranks` cgr USING (group_oid)
      LEFT OUTER JOIN `wwiionline`.`chat_group_vehs_cache` cgv ON (cg.group_oid = cgv.group_oid)
   GROUP  BY 1
  ;
END ;;
DELIMITER ;
