DELIMITER ;;
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_player_details`(
    i_player_id INT(11) UNSIGNED
  , i_arena_id  INT(11) UNSIGNED
  )
    READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
  SELECT  pl.playerid AS `playerid`
       ,  auth.f_player_permissions(pl.playerid) AS `permissions`
       ,  pl.callsign AS `callsign`
       ,  pl.customerid AS `customerid`
       ,  pl.squadid AS `squadid`
       ,  pl.squad_rank AS `squad_rank`
       ,  s.short_name AS `squad_short_name`
       ,  pl.player_decal AS `player_decal`
       ,  pl.locktime AS `lock_unixtime`
       ,  pl.lockside AS `lock_side`
       ,  pl.last_poll AS `last_poll`
       ,  pl.last_login AS `last_login`
       ,  GROUP_CONCAT(DISTINCT(v.group_oid)) AS `groups`
       ,  FROM_UNIXTIME(pl.locktime) AS `lock_datetime`
     ,  NULL AS `minutes`
    FROM  `wwiionline`.`wwii_player` pl
      LEFT OUTER JOIN `auth`.`v_customer_active_groups` v
        ON (pl.customerid = v.customerid AND v.arenaid = i_arena_id)
      LEFT OUTER JOIN `wwiionline`.`wwii_squads` s
        ON (pl.squadid = s.squadid)
   WHERE  pl.playerid = i_player_id
   GROUP  BY pl.playerid
  ;
END ;;
DELIMITER ;
