CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_persona_refresh`(
    i_persona_id INT(11) UNSIGNED
  , i_arena_id  INT(11) UNSIGNED
  )
    READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
  SELECT  pe.rankid AS `rank_id`
       ,  pe.rankpoints AS `rank_points`
       ,  auth.f_player_permissions(pe.playerid) AS `permissions`
       ,  GROUP_CONCAT(DISTINCT(v.group_oid)) AS `groups`
       ,  0 AS `minute_balance`
    FROM  wwiionline.wwii_persona pe
      INNER JOIN wwiionline.wwii_player pl USING (playerid)  
      LEFT OUTER JOIN auth.v_customer_active_groups v
        ON (pl.customerid = v.customerid AND v.arenaid = i_arena_id)
   WHERE  pe.personaid = i_persona_id
   GROUP  BY pe.personaid
  ;
END ;;
DELIMITER ;
