  `instance_oid` bigint(20) unsigned NOT NULL COMMENT 'Assigned by the host, the unique 64-bit ID of the instance. Per campaign.',
  `category_id` smallint(3) unsigned NOT NULL COMMENT 'Instance category',
  `type_id` smallint(3) unsigned NOT NULL COMMENT 'Subkey to category',
  `owner_id` bigint(20) unsigned NOT NULL COMMENT '0 or category/type dependent 64-bit value',
  `created` datetime NOT NULL COMMENT 'Set when the instance is opened',
  `closed` datetime NOT NULL COMMENT 'Host sets this when the instance destructor is called',
  PRIMARY KEY (`instance_oid`),
  UNIQUE KEY `instance_oid` (`instance_oid`)
) ENGINE=MyISAM DEFAULT CHARSET=latin1 COMMENT='Per-campaign history of instances';
