CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_add_kill`(
    i_killer_id INT(11) UNSIGNED
  , i_killer_player_0 INT(11) UNSIGNED
  , i_killer_persona_0 INT(11) UNSIGNED
  , i_killer_player_1 INT(11) UNSIGNED
  , i_killer_persona_1 INT(11) UNSIGNED
  , i_killer_country TINYINT(3) UNSIGNED
  , i_killer_category TINYINT(3) UNSIGNED
  , i_killer_class TINYINT(3) UNSIGNED
  , i_killer_type TINYINT(3) UNSIGNED
  , i_victim_id INT(11) UNSIGNED
  , i_victim_player_0 INT(11) UNSIGNED
  , i_victim_persona_0 INT(11) UNSIGNED
  , i_victim_player_1 INT(11) UNSIGNED
  , i_victim_persona_1 INT(11) UNSIGNED
  , i_victim_country TINYINT(3) UNSIGNED
  , i_victim_category TINYINT(3) UNSIGNED
  , i_victim_class TINYINT(3) UNSIGNED
  , i_victim_type TINYINT(3) UNSIGNED
  , i_kill_value INT(11) UNSIGNED
  , i_dead_x INT(11)
  , i_dead_y INT(11)
  , i_dead_z INT(11)
   )
    MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
  DECLARE l_insert_error TINYINT(1) UNSIGNED DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR SQLSTATE '23000' SET l_insert_error = 1;

  START TRANSACTION;
  INSERT INTO `wwii`.`kills`
    (
      kill_time
    , victim_sortie_id
    , victim_player_0
    , victim_player_1
    , killer_sortie_id
    , killer_player_0
    , killer_player_1
    , dead_x, dead_y, dead_z
    , victim_country, victim_category, victim_class, victim_type
    , victim_vehtype_oid
    , killer_country, killer_category, killer_class, killer_type
    , killer_vehtype_oid
    )
  VALUES
    (
      NOW()
    , i_victim_id
    , i_victim_player_0
    , i_victim_player_1
    , i_killer_id
    , (SELECT kps0.player_id FROM wwiionline.wwii_sortie kps0 WHERE kps0.sortie_id = i_killer_id AND kps0.is_pilot = 1)
    , (SELECT kps1.player_id FROM wwiionline.wwii_sortie kps1 WHERE kps1.sortie_id = i_killer_id AND kps1.is_pilot = 0)
    , i_dead_x, i_dead_y, i_dead_z
    , i_victim_country, i_victim_category, i_victim_class, i_victim_type
    , (SELECT vehtype_oid FROM wwiionline.wwii_vehtype WHERE countryID = i_victim_country AND categoryID = i_victim_category AND classID = i_victim_class AND typeID = i_victim_type)
    , i_killer_country, i_killer_category, i_killer_class, i_killer_type
    , (SELECT vehtype_oid FROM wwiionline.wwii_vehtype WHERE countryID = i_killer_country AND categoryID = i_killer_category AND classID = i_killer_class AND typeID = i_killer_type)
    )
  ;
  IF l_insert_error = 0 THEN COMMIT; ELSE ROLLBACK; END IF;
END ;;
DELIMITER ;
