CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_add_player_note`(
    i_callsign VARCHAR(10) CHARSET ucs2
   , i_issuedBy INT(11) unsigned
   , i_note_type_id INT(11) unsigned
   , i_note text
   )
    MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
  DECLARE l_playerID INT(11) unsigned DEFAULT 0;
  DECLARE l_isPlaynet TINYINT(1) unsigned DEFAULT 0;
  DECLARE l_last_row_fetched INT(11) UNSIGNED DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_last_row_fetched = 1;

  SELECT  p.playerid, p.isPlaynet
    INTO  l_playerID, l_isPlaynet
    FROM  `wwiionline`.`wwii_player` p
   WHERE  p.callsign = LOWER(i_callsign)
  ;

  IF l_last_row_fetched THEN
    SELECT 0 AS err, "No such player" AS txt;
  ELSE
    INSERT  INTO `wwiionline`.`player_notes`
        (playerid, note_type_id, note_at, note_end, note_by, note)
    VALUES  (l_playerID, i_note_type_id, NOW(), NULL, i_issuedBy, i_note)
    ;
    COMMIT;
    SELECT l_playerID AS player;
  END IF;
END ;;
DELIMITER ;
