CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_add_sortie`(
    i_sortie_id INT(11) UNSIGNED
  , i_crew_0_id INT(11) UNSIGNED, i_crew_0_persona_id INT(11) UNSIGNED
  , i_crew_1_id INT(11) UNSIGNED, i_crew_1_persona_id INT(11) UNSIGNED
  , i_brigade_id SMALLINT UNSIGNED
  , i_facility_oid INT(11) UNSIGNED
  , i_weap_country TINYINT(3) UNSIGNED, i_weap_category TINYINT(3) UNSIGNED, i_weap_class TINYINT(3) UNSIGNED, i_weap_type TINYINT(3) UNSIGNED
  , i_mission_type SMALLINT UNSIGNED, i_mission_id INT(11) UNSIGNED
  , i_cell_host_ip TINYINT(3) UNSIGNED
   )
    MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
  IF i_crew_1_id IS NULL or i_crew_1_id = 0 THEN
    INSERT HIGH_PRIORITY INTO `wwiionline`.`wwii_sortie`
      (
        sortie_id
      , player_id, personaid, is_pilot
      , brigade_id, facility_oid
      , vcountry, vcategory, vclass, vtype
      , mission_type, mission_id
      , cell_host_ip
      , added
      , successful
      )
    VALUES
      (
        i_sortie_id
      , i_crew_0_id, i_crew_0_persona_id, 1
      , i_brigade_id, i_facility_oid
      , i_weap_country, i_weap_category, i_weap_class, i_weap_type
      , i_mission_type, i_mission_id
      , i_cell_host_ip
      , NOW()
      , 0
      );
  ELSE
    INSERT HIGH_PRIORITY INTO `wwiionline`.`wwii_sortie`
      (
        sortie_id
      , player_id, personaid, is_pilot
      , brigade_id, facility_oid
      , vcountry, vcategory, vclass, vtype
      , mission_type, mission_id
      , cell_host_ip
      , added
      , successful
      )
    VALUES
      (
        i_sortie_id
      , i_crew_0_id, i_crew_0_persona_id, 1
      , i_brigade_id, i_facility_oid
      , i_weap_country, i_weap_category, i_weap_class, i_weap_type
      , i_mission_type, i_mission_id
      , i_cell_host_ip
      , NOW()
      , 0
      )
    , (
        i_sortie_id
      , i_crew_1_id, i_crew_1_persona_id, 0
      , i_brigade_id, i_facility_oid
      , i_weap_country, i_weap_category, i_weap_class, i_weap_type
      , i_mission_type, i_mission_id
      , i_cell_host_ip
      , NOW()
      , 0
      );
  END IF;
END ;;
DELIMITER ;
