CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_ban_player`(
    i_callsign VARCHAR(10) CHARSET ucs2
   , i_banFor INT(11) unsigned
   , i_issuedBy INT(11) unsigned
   , i_reason text
   )
    MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
  DECLARE l_playerID INT(11) unsigned DEFAULT 0 ;
  DECLARE l_isPlaynet TINYINT(1) unsigned DEFAULT 0 ;

  DECLARE l_note_type_id INT(11) UNSIGNED DEFAULT 0 ;
  DECLARE l_bans INT(11) UNSIGNED DEFAULT 0 ;
  DECLARE l_last_row_fetched INT(11) UNSIGNED DEFAULT 0 ;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_last_row_fetched = 1 ;

  START TRANSACTION ;

  SELECT  p.playerid, p.isPlaynet, (SELECT COUNT(*) FROM `wwiionline`.`player_notes` n WHERE n.playerid = p.playerid AND n.note_type_id = 2)
    INTO  l_playerID, l_isPlaynet, l_bans
    FROM  `wwiionline`.`wwii_player` p
   WHERE  p.callsign = LOWER(i_callsign)
     FOR  UPDATE
  ;

  IF l_last_row_fetched THEN

    ROLLBACK ;
    SELECT 0, "No such player" ;

  ELSEIF l_isPlaynet > 0 THEN

    ROLLBACK ;
    SELECT 0, "Cannot issue bans on CRS accounts" ;

  ELSE

    IF i_banFor > 0 THEN 
      UPDATE  `wwiionline`.`wwii_player`
        SET lockside = 3
        , locktime = UNIX_TIMESTAMP() + i_banFor
      WHERE playerID = l_playerID
      ;

      SET l_bans = l_bans + 1 ;

      INSERT  INTO `wwiionline`.`player_notes`
          (playerid, note_type_id, note_at, note_end, note_by, note)
      VALUES  (l_playerID, 2, NOW(), FROM_UNIXTIME(UNIX_TIMESTAMP() + i_banFor), i_issuedBy, i_reason)
      ;

      COMMIT ;
    ELSE
      ROLLBACK ;
    END IF ;

    SELECT l_playerID, l_bans ;

  END IF ;

END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `p_get_last_killers` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
