CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_last_killers`(
  i_callsign VARCHAR(10) CHARSET ucs2
   )
    READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
    SELECT  k.kill_time
         ,  IF(kp1.callsign IS NOT NULL,CONCAT(kp0.callsign,'/',kp1.callsign),kp0.callsign)
         ,  vv.fullName
         ,  kv.fullName
      FROM  ( wwii.kills k LEFT OUTER JOIN wwiionline.wwii_player kp1 ON (k.killer_player_1 = kp1.playerid) )
            , wwiionline.wwii_player kp0
            , wwiionline.wwii_vehtype vv
            , wwiionline.wwii_vehtype kv
     WHERE  k.victim_player_0 = (SELECT playerid FROM wwiionline.wwii_player WHERE callsign = i_callsign)
      AND k.killer_player_0 = kp0.playerid
      AND k.victim_vehtype_oid = vv.vehtype_oid
      AND k.killer_vehtype_oid = kv.vehtype_oid
     ORDER  BY k.kill_time DESC
     LIMIT  5
     ;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `p_get_last_kills` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8 */ ;
/*!50003 SET character_set_results = utf8 */ ;
/*!50003 SET collation_connection  = utf8_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_last_kills`(
  i_callsign VARCHAR(10) CHARSET ucs2
   )
    READS SQL DATA
    SQL SECURITY INVOKER
BEGIN

    SELECT  k.kill_time AS `kill_time`
     ,  kv.fullName AS `killer_veh`
         ,  IF(vp1.callsign IS NOT NULL,CONCAT(vp0.callsign,'/',vp1.callsign),vp0.callsign) AS `victim_crew`
         ,  vv.fullName AS `victim_veh`
      FROM  ( wwii.kills k LEFT OUTER JOIN wwiionline.wwii_player vp1 ON (k.victim_player_1 = vp1.playerid) )
            , wwiionline.wwii_player vp0
            , wwiionline.wwii_vehtype vv
            , wwiionline.wwii_vehtype kv
     WHERE  k.killer_player_0 = (SELECT playerid FROM wwiionline.wwii_player WHERE callsign = i_callsign)
      AND k.victim_player_0 = vp0.playerid
      AND k.killer_vehtype_oid = kv.vehtype_oid
      AND k.victim_vehtype_oid = vv.vehtype_oid
     ORDER  BY k.kill_time DESC
     LIMIT  5
     ;
END ;;
DELIMITER ;
