CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_persona_data`(
   i_player_id INT(11) UNSIGNED
   , i_country_id TINYINT(3) UNSIGNED
   , i_branch_id TINYINT(3) UNSIGNED
   )
    READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
  DECLARE l_no_match TINYINT(1) UNSIGNED DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_no_match = 1;

  SELECT  p.personaid 
     ,  p.countryid
     ,  p.rankid
     ,  p.rankpoints
     ,  pl.locktime
     ,  pl.lockside
     ,  auth.f_player_permissions(pl.playerid)
     ,  pl.player_decal
     ,  s.squadID
     ,  s.short_name
     ,  0  
     ,  0  
    FROM  wwiionline.wwii_player pl
      LEFT JOIN wwiionline.wwii_persona p ON (pl.playerid = p.playerid)
        LEFT OUTER JOIN wwiionline.wwii_squads s ON (pl.squadID = s.squadID AND s.disbanded = 0)
   WHERE  pl.playerid = i_player_id
      AND p.branchid = i_branch_id
   GROUP  BY p.personaid
   ORDER  BY IF(p.countryID=i_country_id,0,1) ASC
  ;
END ;;
DELIMITER ;
