CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_increase_rank_score`(
    i_playerid INT(11) UNSIGNED
  , i_country INT(11) UNSIGNED
  , i_branch INT(11) UNSIGNED
  , i_personaid INT(11) UNSIGNED
  , i_rankid INT(11) UNSIGNED
  , i_points INT(11) UNSIGNED
   )
    MODIFIES SQL DATA
BEGIN
  UPDATE  wwiionline.wwii_persona
     SET  rankid = i_rankid, rankpoints = i_points
   WHERE  ((personaid = i_personaid) OR (playerid = i_playerid AND countryid = i_country AND branchid = i_branch))
      AND ( rankid < i_rankid OR (rankid = i_rankid AND rankpoints < i_points) )
  ;
END ;;
DELIMITER ;
