DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`wwiiol`@`localhost`*/ /*!50003 TRIGGER toe.tai_supply
  AFTER INSERT ON toe.supply FOR EACH ROW
BEGIN
  DECLARE l_capacity INT(11) UNSIGNED DEFAULT 0;
  SELECT  v.capacity
  INTO  l_capacity
    FROM  wwiionline.strat_hc_units u 
      INNER JOIN toe.vehicles v ON (u.toe_template = v.id)
   WHERE  u.unit_id = NEW.unit_id
      AND v.vehtype_oid = NEW.vehtype_oid
  ;
  INSERT INTO audit.supply
         (unit_id, vehtype_oid, present, capacity)
  VALUES (NEW.unit_id, NEW.vehtype_oid, NEW.present, l_capacity)
  ;
END */;;
DELIMITER ;
