  `id` char(10) NOT NULL,
  `vehtype_oid` int(11) unsigned NOT NULL,
  `capacity` int(11) unsigned NOT NULL DEFAULT '0',
  `cycle0` int(11) unsigned NOT NULL DEFAULT '0',
  `modified` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `resupply_time_m` smallint(5) unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`,`vehtype_oid`),
  KEY `vehtype_oid` (`vehtype_oid`),
  CONSTRAINT `vehicles_ibfk_1` FOREIGN KEY (`id`) REFERENCES `headers` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `vehicles_ibfk_2` FOREIGN KEY (`vehtype_oid`) REFERENCES `wwiionline`.`wwii_vehtype` (`vehtype_oid`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=ucs2;
